package io.github.devicebridge.core;
import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;
public final class UiSafetyTests {
 public static void main(String[] args)throws Exception{int n=0;Object a=new Object(),b=new Object();List<String> paths=new ArrayList<>();paths.add("/sdcard/x");SessionBinding<Object> clipboard=new SessionBinding<>(a,paths);paths.clear();if(clipboard.objects().size()!=1)throw new AssertionError("Mutable selection escaped");n++;if(clipboard.require(a)!=a)throw new AssertionError();n++;try{clipboard.require(b);throw new AssertionError("Cross-device clipboard accepted");}catch(IllegalStateException expected){n++;}SessionBinding<Object> flash=new SessionBinding<>(a,Arrays.asList("boot","image.img"));try{flash.require(b);throw new AssertionError("Stale destructive approval accepted");}catch(IllegalStateException expected){n++;}try{flash.objects().clear();throw new AssertionError("Mutable approval");}catch(UnsupportedOperationException expected){n++;}
  AtomicInteger closed=new AtomicInteger();OperationScope scope=new OperationScope();scope.own((Closeable)closed::incrementAndGet);scope.close();scope.close();if(closed.get()!=1)throw new AssertionError("Resource close not idempotent");n++;try{scope.checkActive();throw new AssertionError("Cancelled operation resumed");}catch(InterruptedIOException expected){n++;}try{scope.own((Closeable)closed::incrementAndGet);throw new AssertionError("Late resource leaked");}catch(InterruptedIOException expected){n++;}if(closed.get()!=2)throw new AssertionError("Late resource was not closed");n++;OperationScope live=new OperationScope();Closeable kept=closed::incrementAndGet;live.own(kept);live.release(kept);live.close();if(closed.get()!=2)throw new AssertionError("Released resource closed");n++;OperationScope async=new OperationScope();AtomicInteger asyncClosed=new AtomicInteger();List<Runnable> queued=new ArrayList<>();async.own((Closeable)asyncClosed::incrementAndGet);async.cancelAsync(queued::add);if(!async.isCancelled()||asyncClosed.get()!=0||queued.size()!=1)throw new AssertionError("Async cancel must mark before closing");n++;try{async.checkActive();throw new AssertionError("Async cancelled operation resumed");}catch(InterruptedIOException expected){n++;}queued.get(0).run();if(asyncClosed.get()!=1)throw new AssertionError("Queued close did not run");n++;async.cancelAsync(queued::add);if(queued.size()!=1)throw new AssertionError("Async cancellation not idempotent");n++;if(!SessionBinding.matchesView(a,a,a,7,7,true))throw new AssertionError("Current dialog rejected");n++;
  if(SessionBinding.matchesView(a,b,b,7,7,true))throw new AssertionError("Old dialog used new device");n++;
  if(SessionBinding.matchesView(a,a,a,7,8,true))throw new AssertionError("Old dialog used later page");n++;
  if(SessionBinding.matchesView(a,a,b,7,7,true))throw new AssertionError("Hidden target view accepted");n++;
  if(SessionBinding.matchesView(a,a,a,7,7,false))throw new AssertionError("Dead session view accepted");n++;
  if(SessionBinding.matchesView(null,null,null,7,7,true))throw new AssertionError("Missing session accepted");n++;
  System.out.println("UI SAFETY TESTS: "+n+" passed");}
}
